//! Rule 22 in the guest against the shared action-kit vectors (packages/pca-conformance/vectors/actions, generated by the TS
//! reference): schema floor integrity (`rule22_schema`), the floor decision (`rule22`), a single verb's integrity (`schema_verb`),
//! the unsigned schema shape (`schema_shape`) and closed-world conformance of version 2 verbs (`conform`). `pins` (the verifier's
//! reviewer keys) is optional everywhere: absent = no verb is confirmed. Every vector must reproduce the reference exactly.
use pca_zkvm_core::action_schema::{action_schema_shape_error, conform_action};
use pca_zkvm_core::rule22::{decide, extend_registry, schema_floor_error, schema_verb_floor_error, core_registry, GrantFacts};
use serde_json::{json, Value};
use std::collections::BTreeSet;

fn vectors(kind: &str) -> Vec<Value> {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../packages/pca-conformance/vectors/actions");
    let mut out = Vec::new();
    for e in std::fs::read_dir(dir).expect("vectors dir") {
        let p = e.unwrap().path();
        // the `*-lone-surrogate` vectors (parse-adv-, approval-render-adv-) carry an escape serde_json refuses; the kinds replayed here have none
        let name = p.file_name().unwrap().to_string_lossy().to_string();
        if name.ends_with(".json") && !name.starts_with("parse-") && !name.contains("lone-surrogate") {
            let v: Value = serde_json::from_str(&std::fs::read_to_string(&p).unwrap()).unwrap();
            if v["kind"] == kind {
                out.push(v);
            }
        }
    }
    out.sort_by(|a, b| a["id"].as_str().cmp(&b["id"].as_str()));
    out
}

const CODES: [&str; 5] = ["schema_floor_forged", "schema_traits_forged", "unknown_trait", "traits_digest_mismatch", "bad_registry"];
fn code_of(e: Option<String>) -> Value {
    match e {
        None => json!({"ok": true}),
        Some(e) => json!({"ok": false, "code": CODES.iter().find(|c| e.contains(*c)).copied().unwrap_or("unknown")}),
    }
}

#[test]
fn schema_floor_integrity_matches_the_reference() {
    let vs = vectors("rule22_schema");
    assert!(vs.len() >= 15);
    for v in vs {
        assert_eq!(code_of(schema_floor_error(&v["input"]["doc"], v["input"].get("pins"))), v["expect"], "{}", v["id"]);
    }
}

#[test]
fn floor_decision_matches_the_reference() {
    let vs = vectors("rule22");
    assert!(vs.len() >= 8);
    for v in vs {
        let i = &v["input"];
        let (integrity, decision) = match schema_floor_error(&i["doc"], i.get("pins")) {
            Some(e) => (CODES.iter().find(|c| e.contains(*c)).copied().unwrap_or("unknown"), 0u8),
            None => {
                let g = &i["grant"];
                let facts = GrantFacts {
                    caveats: g["caveats"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect::<BTreeSet<_>>(),
                    max_esc: g["max_esc"].as_i64().unwrap(),
                    preauth_esc: g["preauth_esc"].as_i64().unwrap(),
                };
                let ctx: Vec<String> = i["context"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
                ("ok", decide(&i["doc"], i["verb"].as_str().unwrap(), &facts, &ctx))
            }
        };
        let name = ["deny", "escalate", "allow"][decision as usize];
        assert_eq!(json!({"integrity": integrity, "decision": name}), v["expect"], "{}", v["id"]);
    }
}

#[test]
fn single_verb_integrity_matches_the_reference() {
    let vs = vectors("schema_verb");
    assert!(vs.len() >= 15);
    for v in vs {
        let i = &v["input"];
        let reg = match i.get("custom_traits").and_then(Value::as_array) {
            Some(c) => match extend_registry(c) {
                Ok(r) => r,
                Err(_) => {
                    assert_eq!(v["expect"], json!({"error": true}), "{}", v["id"]);
                    continue;
                }
            },
            None => core_registry(),
        };
        let got = schema_verb_floor_error(&i["verb"], &reg, i.get("pins"));
        assert_eq!(code_of(got), v["expect"], "{}", v["id"]);
    }
}

#[test]
fn unsigned_schema_shape_matches_the_reference() {
    let vs = vectors("schema_shape");
    assert!(vs.len() >= 20);
    for v in vs {
        assert_eq!(json!({"ok": action_schema_shape_error(&v["input"]["doc"], false).is_none()}), v["expect"], "{}", v["id"]);
    }
}

#[test]
fn conformance_matches_the_reference_for_v2_verbs() {
    let vs = vectors("conform");
    assert!(vs.len() >= 20);
    for v in vs {
        let i = &v["input"];
        let got = match conform_action(&i["schema"], i["verb"].as_str().unwrap(), &i["params"]) {
            Ok(()) => json!({"ok": true}),
            Err(c) => json!({"ok": false, "code": c.code}),
        };
        assert_eq!(got, v["expect"], "{}", v["id"]);
    }
}

fn schema_with(verb: Value, v: i64) -> Value {
    json!({"v": v, "kind": "pca-action-schema", "site": "https://s.example", "aud": "s.example", "version": "1", "verbs": [verb], "sig": {"alg": "ed25519", "kid": "k", "value": "AA"}})
}

#[test]
fn v2_shape_is_accepted_and_v1_is_unchanged() {
    // a derived v2 verb from the vectors is shape-valid in a v2 document and its v2 members are unknown members of a v1 document
    let v = vectors("schema_verb").into_iter().find(|v| v["id"] == "schema-verb-ok-000").unwrap();
    let verb = v["input"]["verb"].clone();
    assert_eq!(action_schema_shape_error(&schema_with(verb.clone(), 2), true), None);
    assert!(action_schema_shape_error(&schema_with(verb, 1), true).is_some_and(|e| e.contains("unknown member")));
    assert_eq!(action_schema_shape_error(&schema_with(json!({"verb": "a.b", "kind": "write", "params": {}}), 3), true), Some("unsupported schema version".into()));
}

#[test]
fn v2_value_domains() {
    use pca_zkvm_core::action_schema::param_value_violation as pv;
    let d = |t: &str, extra: Value| {
        let mut o = json!({"type": t, "semantic": "x", "sensitivity": "free"});
        for (k, v) in extra.as_object().unwrap() {
            o[k] = v.clone();
        }
        o
    };
    assert!(pv(&d("datetime", json!({})), &json!("2026-10-26T10:00:00Z")).is_none());
    assert!(pv(&d("datetime", json!({})), &json!("2026-10-26T10:00:00.123Z")).is_none());
    for bad in ["2026-10-26T10:00:00+00:00", "2026-02-30T10:00:00Z", "2026-10-26T24:00:00Z", "2026-10-26 10:00:00Z", "2026-10-26T10:00:00.1234Z"] {
        assert!(pv(&d("datetime", json!({})), &json!(bad)).is_some(), "{bad}");
    }
    assert!(pv(&d("duration", json!({"max": 10})), &json!(10)).is_none());
    assert!(pv(&d("duration", json!({"max": 10})), &json!(11)).is_some());
    assert!(pv(&d("duration", json!({})), &json!(-1)).is_some());
    assert!(pv(&d("object_ref", json!({})), &json!("")).is_some());
    for (f, ok, bad) in [
        ("email", "a@b.co", "a@b"),
        ("iban", "GB82WEST12345698765432", "GB82WEST12345698765433"),
        ("uuid", "123e4567-e89b-12d3-a456-426614174000", "123E4567-e89b-12d3-a456-426614174000"),
        ("cidr", "10.0.0.0/8", "10.0.0.0/33"),
        ("semver", "1.2.3-rc.1+build.5", "01.2.3"),
        ("uri_https", "https://e.co/x", "http://e.co"),
        ("phone_e164", "+14155550100", "+0123456"),
        ("iso_country", "DE", "de"),
        ("id:acme.customer", "cus_1", "bad id"),
    ] {
        let dd = d("string", json!({"format": f}));
        assert!(pv(&dd, &json!(ok)).is_none(), "{f} {ok}");
        assert!(pv(&dd, &json!(bad)).is_some(), "{f} {bad}");
    }
}

// ---- the pipeline: schema (integrity) and traits (decision) through decide_intent_v2 ----------------------------------------

use pca_zkvm_core::canonical::canonical_bytes;
use pca_zkvm_core::commit::{b64u, hash_canonical};
use pca_zkvm_core::intent_v2::decide_intent_v2;
use ed25519_dalek::{Signer, SigningKey};

const NOW: f64 = 1_800_000_000_000.0;

fn signed(mut doc: Value, sk: &SigningKey) -> Value {
    doc.as_object_mut().unwrap().remove("sig");
    let mut msg = b"atlas-pca/action-schema/v1\0".to_vec();
    msg.extend_from_slice(&canonical_bytes(&doc));
    doc["sig"] = json!({"alg": "ed25519", "kid": "k1", "value": b64u(&sk.sign(&msg).to_bytes())});
    doc
}

fn grant(actions: Value) -> Value {
    let mut env = json!({
        "type": "envelope", "goal_commit": "g", "predicates": [], "caveats": [], "agent_binding": {},
        "risk_policy": {"weights": {"alpha": 0, "beta": 0, "gamma": 1, "delta": 0, "epsilon": 0, "zeta": 0}, "theta1": 1, "theta2": 1, "kappa": 100, "lambda": 0, "rho": 0.5, "bMax": 1000000}
    });
    if !actions.is_null() {
        env["actions"] = actions;
    }
    json!({"caveats": [env]})
}

#[test]
fn schema_and_traits_checks_through_the_pipeline() {
    let sk = SigningKey::from_bytes(&[7u8; 32]);
    let key = json!({"kid": "k1", "alg": "ed25519", "pk": b64u(sk.verifying_key().as_bytes())});
    // the honest document of the vectors, re-addressed to this audience and signed
    let v = vectors("rule22_schema").into_iter().find(|v| v["id"] == "rule22-schema-honest").unwrap();
    let mut doc = v["input"]["doc"].clone();
    doc["aud"] = json!("s.example");
    let verb = doc["verbs"].as_array().unwrap().iter().find(|x| x["verb"] == "stripe.refund").unwrap().clone();
    let floors = verb["floors"].clone();
    let params = json!({"amount": 100, "charge": "ch_12345678", "idempotency_key": "k"});
    let p = json!({"aud": "s.example", "action": {"verb": "stripe.refund", "resource": "x", "params_digest": hash_canonical(&params)}});
    let pins = v["input"]["pins"].clone();
    let run = |doc: &Value, g: &Value, call_context: Value| {
        let ctx = json!({"policy": {"schema": {"closed_world": true}}, "params": params, "schema": {"docs": [signed(doc.clone(), &sk)], "keys": [key]}, "call_context": call_context, "reviewers": pins});
        decide_intent_v2(&p, g, Some(&ctx), NOW).checks.iter().map(|c| (c.name, c.ok, c.reason.clone().unwrap_or_default())).collect::<Vec<_>>()
    };
    let provides = json!({"pack": {"ns": "stripe", "root": "A".repeat(43)}, "on_new_action": "deny", "max_esc": 3, "preauth_esc": floors["esc"], "caveats": floors["caveats"]});
    let ctx_ok = floors["context"].clone();
    // honest document, grant provides the floors, verifier observed the context: both checks pass
    let r = run(&doc, &grant(provides.clone()), ctx_ok.clone());
    assert_eq!(r.iter().map(|(n, ok, _)| (*n, *ok)).collect::<Vec<_>>(), vec![("schema", true), ("traits", true)], "{r:?}");
    // a grant that provides no caveat kinds: escalate (a failing check whose reason starts `escalate:`)
    let mut weak = provides.clone();
    weak["caveats"] = json!([]);
    let r = run(&doc, &grant(weak), ctx_ok.clone());
    assert!(r[1].0 == "traits" && !r[1].1 && r[1].2.starts_with("escalate:"), "{r:?}");
    // a tier above max_esc: deny (no escalate prefix)
    let mut low = provides.clone();
    low["max_esc"] = json!(0);
    low["preauth_esc"] = json!(0);
    let r = run(&doc, &grant(low), ctx_ok.clone());
    assert!(r[1].0 == "traits" && !r[1].1 && !r[1].2.starts_with("escalate:"), "{r:?}");
    // the verifier observed no context: escalate if the floors need any
    if floors["context"].as_array().is_some_and(|a| !a.is_empty()) {
        let r = run(&doc, &grant(provides.clone()), json!([]));
        assert!(!r[1].1 && r[1].2.starts_with("escalate:"), "{r:?}");
    }
    // forged floors / dropped implied trait: the schema check fails and traits is not evaluated
    let mut forged = doc.clone();
    let i = forged["verbs"].as_array().unwrap().iter().position(|x| x["verb"] == "stripe.refund").unwrap();
    forged["verbs"][i]["floors"]["esc"] = json!(0);
    forged["verbs"][i]["floors"]["caveats"] = json!([]);
    let r = run(&forged, &grant(provides.clone()), ctx_ok.clone());
    assert_eq!(r.len(), 1, "{r:?}");
    assert!(r[0].0 == "schema" && !r[0].1 && r[0].2.contains("schema_floor_forged"), "{r:?}");
    let mut dropped = doc.clone();
    dropped["verbs"][i]["traits"] = json!([]);
    let r = run(&dropped, &grant(provides.clone()), ctx_ok.clone());
    assert!(r[0].2.contains("schema_traits_forged"), "{r:?}");
    // the same honest document under a verifier that pins no reviewer: every verb is unconfirmed, so it must carry every trait
    let ctx = json!({"policy": {"schema": {"closed_world": true}}, "params": params, "schema": {"docs": [signed(doc.clone(), &sk)], "keys": [key]}, "call_context": ctx_ok});
    let r = decide_intent_v2(&p, &grant(provides.clone()), Some(&ctx), NOW);
    assert!(!r.checks[0].ok && r.checks[0].reason.as_deref().is_some_and(|x| x.contains("unconfirmed action must carry every trait")), "{:?}", r.checks);
    // a malformed reviewers context fails closed
    let ctx = json!({"policy": {"schema": {"closed_world": true}}, "reviewers": {"keys": "x"}});
    assert!(decide_intent_v2(&p, &grant(Value::Null), Some(&ctx), NOW).checks.iter().all(|c| !c.ok && c.reason.as_deref().is_some_and(|x| x.contains("reviewers"))));
    // a malformed call_context fails every reported check closed
    let ctx = json!({"policy": {"schema": {"closed_world": true}}, "call_context": "x"});
    let r = decide_intent_v2(&p, &grant(Value::Null), Some(&ctx), NOW);
    assert!(r.checks.iter().all(|c| !c.ok && c.reason.as_deref().is_some_and(|x| x.contains("call_context"))));
}
